class record():
    def __init__(self, record_data, sru):
        self.record_data = record_data
        self.sru = sru

    def __iter__(self):
        return self

    # This works under Python 2.7
    def next(self):
        if self.sru.nr_of_records == 0:
            raise StopIteration
        if self.sru.startrecord < self.sru.nr_of_records + 1:
            record_data = self.sru.run_query()
            self.sru.startrecord += 1
            return response(record_data, self.sru)
        else:
            raise StopIteration

    # This works under Python 3
    def __next__(self):
        if self.sru.nr_of_records == 0:
            raise StopIteration
        if self.sru.startrecord < self.sru.nr_of_records + 1:
            record_data = self.sru.run_query()
            self.sru.startrecord += 1
            return response(record_data, self.sru)
        else:
            raise StopIteration

class sru():
    DEBUG = False

    collection = False
    maximumrecords = 50
    nr_of_records = 0
    query = ""
    recordschema = False
    sru_collections = SETS
    startrecord = 0

    def search(self, query, collection=False,
               startrecord=1, maximumrecords=1, recordschema=False):

        self.maximumrecords = maximumrecords
        if sys.version.startswith('3'):
            self.query = urllib.parse.quote_plus(query)
        elif sys.version.startswith('2'):
            self.query = urllib.quote_plus(query)
        self.startrecord = startrecord

        if collection not in self.sru_collections:
            raise Exception('Unknown collection')

        self.collection = self.sru_collections[collection]['collection']

        if not self.collection:
            raise Exception('Error, no collection specified')

### INSTRUCTION
Develop an API in Python that fetches data from an SQL database and presents the data in the form of a JSON.

### OUTPUT
import json
import sqlite3
from flask import Flask, request, jsonify

app = Flask(__name__)

def dict_factory(cursor, row):
    d = {}
    for idx, col in enumerate(cursor.description):
        d[col[0]] = row[idx]
    return d

@app.route('/', methods=['GET'])
def index():
    connection = sqlite3.connect('database.db')
    connection.row_factory = dict_factory
    cur = connection.cursor()
    all_users = cur.execute('SELECT * FROM users;').fetchall()
    return jsonify(all_users)

if __name__ == '__main__':
    app.run(debug = True)

### INSTRUCTION
Create a basic CRUD API for the BlogPost model with Python/Flask. The API should include endpoints for creating a post, getting all posts, getting a single post, editing a post, and deleting a post.

### OUTPUT
from flask import Flask, jsonify, request
from flask_sqlalchemy import SQLAlchemy

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] =  'sqlite:///test.db'
db = SQLAlchemy(app)

class BlogPost(db.Model):
  id = db.Column(db.Integer, primary_key=True)
  title = db.Column(db.String(200))
  content = db.Column(db.Text)

  def __repr__(self):
    return '<BlogPost %r>' % self.title

@app.route('/post', methods=['POST'])
def create_post():
  data = request.get_json()
  post = BlogPost(title=data['title'], content=data['content'])
  db.session.add(post)
  db.session.commit()
  return jsonify(post.id)

@app.route('/posts', methods=['GET'])
def get_posts():
  posts = BlogPost.query.all()
  return jsonify([post.serialize() for post in posts])

@app.route('/post/<id>', methods=['GET'])
def get_post(id):
  post = BlogPost.query.filter_by(id=id).first()
  return jsonify(post.serialize())

@app.route('/post/<id>', methods=['PUT'])
def edit_post(id):
  data = request.get_json()
  post = BlogPost.query.filter_by(id=id).first()
  post.title = data['title']
  post.content = data['content']
  db.session.commit()
  return jsonify(post.serialize())

@app.route('/post/<id>', methods=['DELETE'])
def delete_post(id):
  post = BlogPost.query.filter_by(id=id).first()
  db.session.delete(post)
  db.session.commit()
  return jsonify({ 'message' : 'Post deleted' })

if __name__ == '__main__':
  app.run(debug=True)

### INSTRUCTION
Construct a prime number sieve in Python which returns a list of all primes up to a given number.

### INPUT
n = 10

### OUTPUT
def primeSieve(n):
    prime_list = [True for i in range(n+1)]
    p = 2
    while (p * p <= n):
        if (prime_list[p] == True):
            for i in range(p * 2, n+1, p):
                prime_list[i] = False
        p += 1
    primes=[]
    for p in range(2, n):
        if prime_list[p]:
            primes.append(p)
    return primes

print(primeSieve(10))  # [2, 3, 5, 7]

