}

const char* pos2str(DWORD pos) {
    switch (pos) {
    case WFS_CDM_POSLEFT: return "LEFT";
    case WFS_CDM_POSRIGHT: return "RIGHT";
    case WFS_CDM_POSFRONT: return "FRONT";
    case WFS_CDM_POSREAR: return "REAR";
